'use strict';

/**
* Generate a single-precision complex floating-point Vandermonde matrix.
*
* @module @stdlib/blas/ext/base/cvander
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var cvander = require( '@stdlib/blas/ext/base/cvander' );
*
* var x = new Complex64Array( [ 1.0, 0.0, 2.0, 0.0 ] );
* var out = new Complex64Array( 6 );
*
* cvander( 'row-major', -1, 2, 3, x, 1, out, 3 );
* // out => <Complex64Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var cvander = require( '@stdlib/blas/ext/base/cvander' );
*
* var x = new Complex64Array( [ 1.0, 0.0, 2.0, 0.0 ] );
* var out = new Complex64Array( 6 );
*
* cvander.ndarray( -1, 2, 3, x, 1, 0, out, 3, 1, 0 );
* // out => <Complex64Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var cvander;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	cvander = main;
} else {
	cvander = tmp;
}


// EXPORTS //

module.exports = cvander;

// exports: { "ndarray": "cvander.ndarray" }
